const CANON_WEBHOOKS = [
  { name: 'PDCA',   events: ['reply'],            url: 'https://n8n.coldunicorn.com/webhook/aimfox-classifier' },
  { name: 'preMQL', events: ['lead_label_added'], url: 'https://n8n.coldunicorn.com/webhook/preMQL-Aimfox' },
];
const CANON_LABELS = [{ name: 'preMQL', color: 'yellow' }, { name: 'MQL', color: 'success' }];
// A webhook's identity is events + url, NEVER its name. GIC's webhook is called "Manual Tag",
// hits the right URL on the right event, and matching by name would have created a second one.
const hookKey = (events, url) => `${[...(events ?? [])].map(String).sort().join('+')} ${String(url ?? '').trim()}`;
const isDryRun = () => $('Input').first().json.dry_run !== false;

// State BEFORE any write. What leaves here is either returned as is (dry_run / nothing missing)
// or merged with what Create Missing actually created, in Merge Outcomes.
const client = $('Resolve Client').first().json ?? {};
const key = $('Effective Key').first().json ?? {};
const hooksRaw = $('List Webhooks').first().json ?? {};
const labelsRaw = $('List Labels').first().json ?? {};

const errored = (raw) => Boolean(raw?.error) || raw?.status === 'fail';
const step = (outcome, present = [], missing = [], error = null) => ({
  outcome, present, ...(missing.length ? { missing } : {}), ...(error ? { error } : {}),
});

const keyStep = key.key_source === 'stored' ? step('ok', ['client_sequencers.api_key'])
  : key.key_source === 'vendor' ? step('ok', [`vendor token reused (${key.vendor_tokens} at the vendor)`])
  : key.key_source === 'minted' ? step('created', [], [], null)
  : step('missing', [], ['api_key'], key.mint_error ?? (isDryRun() ? 'no key stored and none at the vendor' : 'mint did not run'));

const haveKey = Boolean(key.api_key);

const listStep = (raw, arrayKey, canon, identity) => {
  if (!haveKey) return step('skipped', [], [], 'no workspace key available');
  if (errored(raw)) return step('skipped', [], [], 'vendor call failed');
  const present = (raw[arrayKey] ?? []).map(identity);
  const missing = canon.map(identity).filter((k) => !present.includes(k));
  return step(missing.length ? 'missing' : 'ok', present, missing);
};

const webhooks = listStep(hooksRaw, 'webhooks', CANON_WEBHOOKS, (w) => hookKey(w.events, w.url));
const labels = listStep(labelsRaw, 'labels', CANON_LABELS, (l) => String(l?.name ?? ''));

return [{ json: {
  client_id: $('Input').first().json.client_id,
  client_name: client.client_name ?? null,
  sequencer: 'aimfox',
  dry_run: isDryRun(),
  resolved: ($('Resolve Workspace').first().json ?? {}).resolved ?? null,
  steps: {
    key: keyStep, webhooks, labels,
    campaigns: step('skipped', [], [], 'catalogued by aimfox-campaign-sync, not created here'),
  },
} }];

// Fold N vendor responses back into one item. n8n preserves item order, so the i-th response
// belongs to the i-th planned element.
// n8n reports a node error as { message, error }, and error is an object. A naive String(err)
// gives `[object Object]` — a string that says nothing. That is what the first live run returned.
const describe = (v) => {
  if (v == null) return null;
  if (typeof v === 'string') return v;
  return v.message ?? v.description ?? (() => { try { return JSON.stringify(v); } catch (e) { return String(v); } })();
};

const planned = $('Plan Writes').all().map((i) => i.json);
const results = $input.all().map((i) => i.json ?? {});
const created = [];
const failed = [];
planned.forEach((p, i) => {
  const r = results[i] ?? {};
  // statusCode ONLY. The `status` field here is the vendor's, not HTTP: Aimfox answers success
  // with status:"ok", and Number('ok') is NaN — reading it as a code scores a failure as success.
  const code = Number(r.statusCode ?? 0);
  const bad = Boolean(r.error) || code >= 400;
  if (bad) failed.push(`${p.identity} — ${describe(r.message ?? r.error) ?? 'HTTP ' + code}`);
  else created.push(p.identity);
});
return [{ json: { created, failed } }];

// Which workspace key the rest of the run uses. Order: stored → already present at the vendor →
// freshly minted. POST /tokens is not an upsert — it issues ANOTHER token every time, so reading
// before writing is not an optimisation; it is the only thing that keeps one key per workspace.
const client = $('Resolve Client').first().json ?? {};
const tokensRaw = $('List Tokens').first().json ?? {};
const vendor = Array.isArray(tokensRaw.tokens) ? tokensRaw.tokens
  : Array.isArray(tokensRaw.data) ? tokensRaw.data : [];
const vendorToken = vendor.find((t) => t?.token)?.token ?? null;

let minted = null;
let mint_error = null;
if ($('Mint Key').isExecuted) {
  const m = $('Mint Key').first().json ?? {};
  minted = m.token ?? m.data?.token ?? null;
  if (!minted) mint_error = String(m.error?.message ?? m.error ?? 'mint returned no token');
}

const stored = client.api_key || null;
const api_key = stored ?? vendorToken ?? minted;
const key_source = stored ? 'stored' : vendorToken ? 'vendor' : minted ? 'minted' : 'none';

// key_to_store is what Record must put into client_sequencers.api_key. Rewriting a stored key
// with itself is pointless; a vendor key must be stored, or the next run goes looking for it
// again and the read nodes silently fail with 401 without it.
return [{ json: {
  api_key,
  key_source,
  key_to_store: key_source === 'stored' ? null : api_key,
  vendor_tokens: vendor.length,
  mint_error,
} }];

// n8n reports a node error as { message, error }, and error is an object. A naive String(err)
// gives `[object Object]` — a string that says nothing. That is what the first live run returned.
const describe = (v) => {
  if (v == null) return null;
  if (typeof v === 'string') return v;
  return v.message ?? v.description ?? (() => { try { return JSON.stringify(v); } catch (e) { return String(v); } })();
};

const out = $('Merge Outcomes').first().json;
const rec = $json ?? {};
const failed = Boolean(rec.error);
return [{ json: {
  ...out,
  recorded: !failed,
  ...(failed ? { record_error: describe(rec.message ?? rec.error) } : {}),
} }];

// One entry point for two triggers. A webhook puts the payload in body; the sub-workflow trigger
// puts it at the root. Without this node every $('Start') would throw on a webhook run.
const fromWebhook = $('Webhook').isExecuted;
const raw = fromWebhook ? ($('Webhook').first().json?.body ?? {}) : ($('Start').first().json ?? {});

// dry_run: anything but an EXPLICIT boolean false is a dry run. The string 'false' does not count.
// That matters more on an open webhook than in the UI: the body arrives from the network, and
// neither a forgotten field nor a wrong type may mean "write into the client's system".
return [{ json: {
  client_id: raw.client_id ?? null,
  workspace_id: raw.workspace_id ?? null,
  dry_run: raw.dry_run === false ? false : true,
  requested_by: raw.requested_by ?? null,
  via: fromWebhook ? 'webhook' : 'sub-workflow',
} }];

// One shape for Record and for the response. Runs both after creation and around it.
const base = $('Build Result').first().json;
const steps = JSON.parse(JSON.stringify(base.steps));

if ($('Collect Creates').isExecuted) {
  const { created = [], failed = [] } = $('Collect Creates').first().json ?? {};
  for (const name of ['webhooks', 'labels']) {
    const st = steps[name];
    const wanted = st.missing ?? [];
    const done = wanted.filter((k) => created.includes(k));
    const bad = wanted.filter((k) => failed.some((f) => f.startsWith(k + ' —')));
    if (done.length) st.created = done;
    st.missing = wanted.filter((k) => !done.includes(k));
    if (!st.missing.length) delete st.missing;
    st.outcome = bad.length ? 'failed' : done.length ? 'created' : st.outcome;
    if (bad.length) st.error = failed.filter((f) => bad.some((k) => f.startsWith(k + ' —'))).join('; ');
  }
}

const decided = [steps.key, steps.webhooks, steps.labels];
const good = (s) => s.outcome === 'ok' || s.outcome === 'created';
const state = decided.every(good) ? 'configured'
  : decided.every((s) => !good(s)) ? 'missing'
  : 'partial';

// setup_state NEVER holds a key — invariant 7. There is none here: steps describe presence,
// not values.
return [{ json: { ...base, state, steps } }];

const input = $('Input').first().json;
const client = $('Resolve Client').first().json ?? {};
const resolution = $('Resolve Workspace').first().json ?? {};

// A client that does not exist is the caller's error, not a provisioning state. But it has to
// be said out loud: a silent stop with status=success is how Audytel's leads disappeared.
const state = resolution.client_missing ? 'client_not_found' : 'needs_selection';
const reason = resolution.client_missing ? 'no client with that id — Resolve Client left-joins the connector, so a client without one still resolves'
  : resolution.ambiguous ? 'more than one workspace matches the client name'
  : resolution.list_error ? `could not list workspaces: ${resolution.list_error}`
  : 'no workspace matches the client name';

return [{ json: {
  client_id: input.client_id,
  client_name: client.client_name ?? null,
  sequencer: 'aimfox',
  dry_run: $('Input').first().json.dry_run !== false,
  resolved: null,
  state,
  reason,
  candidates: resolution.candidates ?? [],
  steps: {
    key: { outcome: 'skipped' }, webhooks: { outcome: 'skipped' },
    labels: { outcome: 'skipped' }, campaigns: { outcome: 'skipped' },
  },
} }];

const CANON_WEBHOOKS = [
  { name: 'PDCA',   events: ['reply'],            url: 'https://n8n.coldunicorn.com/webhook/aimfox-classifier' },
  { name: 'preMQL', events: ['lead_label_added'], url: 'https://n8n.coldunicorn.com/webhook/preMQL-Aimfox' },
];
const CANON_LABELS = [{ name: 'preMQL', color: 'yellow' }, { name: 'MQL', color: 'success' }];
// A webhook's identity is events + url, NEVER its name. GIC's webhook is called "Manual Tag",
// hits the right URL on the right event, and matching by name would have created a second one.
const hookKey = (events, url) => `${[...(events ?? [])].map(String).sort().join('+')} ${String(url ?? '').trim()}`;
const isDryRun = () => $('Input').first().json.dry_run !== false;

// One item per MISSING element. An empty array means Create Missing does not execute at all —
// that, not a flag, is how dry-run safety works here.
if (isDryRun()) return [];

const s = $json.steps ?? {};
const out = [];
for (const c of CANON_WEBHOOKS) {
  const id = hookKey(c.events, c.url);
  if ((s.webhooks?.missing ?? []).includes(id)) {
    out.push({ json: { kind: 'webhook', identity: id, url: 'https://api.aimfox.com/api/v2/webhooks',
      body: { name: c.name, events: c.events, url: c.url, integration: false } } });
  }
}
for (const c of CANON_LABELS) {
  if ((s.labels?.missing ?? []).includes(c.name)) {
    out.push({ json: { kind: 'label', identity: c.name, url: 'https://api.aimfox.com/api/v2/labels',
      body: { name: c.name, color: c.color } } });
  }
}
return out;

