// Resolution order: explicit id → already claimed by this client → EXACT name match → candidates.
//
// The "claimed" step is load-bearing. Measured 2026-08-07: the client name matches the workspace
// name in only 4 cases out of 9 ("Bent Iron PL" vs "Bent Iron", "FortumEnergia" vs "Fortum",
// "ColdUnicorn PL" vs "Łukasz Kot"). For an established client the workspace is known from the
// database, so no name search is needed — otherwise Bent Iron PL lands in needs_selection for free.
//
// Ambiguity is never resolved by guessing — invariant 2. A guess is exactly what put GIC's
// workspace on the client Prac.Finansowa.
const input = $('Input').first().json;
const client = $('Resolve Client').first().json ?? {};
const listRaw = $('List Workspaces').first().json ?? {};
const claimedRaw = $('Read Claimed').first().json ?? {};

const list = Array.isArray(listRaw.workspaces) ? listRaw.workspaces
  : Array.isArray(listRaw.data) ? listRaw.data
  : [];
const idOf = (w) => String(w?.id ?? w?.workspace_id ?? '').trim();
const nameOf = (w) => String(w?.name ?? '').trim();

const claimed = new Set((claimedRaw.claimed ?? []).map(String));
const listError = listRaw.error ? String(listRaw.error?.message ?? listRaw.error) : null;
const base = { candidates: [], list_error: listError, workspaces_seen: list.length };

// Resolve Client has alwaysOutputData, so a missing client arrives as {} instead of quietly
// ending the chain. Say it out loud — a silent success is worse than an error.
if (!String(client.client_name ?? '').trim()) {
  return [{ json: { ...base, resolved: null, client_missing: true } }];
}

const nameFor = (id) => nameOf(list.find((w) => idOf(w) === id)) || null;

const explicit = String(input.workspace_id ?? '').trim();
if (explicit) {
  return [{ json: { ...base, resolved: { workspace_id: explicit, name: nameFor(explicit), matched_by: 'explicit' } } }];
}

const stored = String(client.stored_workspace_id ?? '').trim();
if (stored) {
  return [{ json: { ...base, resolved: { workspace_id: stored, name: nameFor(stored), matched_by: 'stored' } } }];
}

const target = String(client.client_name).trim().toLowerCase();
const matches = list.filter((w) => nameOf(w).toLowerCase() === target);
if (matches.length === 1) {
  return [{ json: { ...base, resolved: { workspace_id: idOf(matches[0]), name: nameOf(matches[0]), matched_by: 'name' } } }];
}

// Candidates are everything not yet claimed by any client. Offering a taken workspace would
// invite the same wrong assignment all over again.
const candidates = list
  .filter((w) => idOf(w) && !claimed.has(idOf(w)))
  .map((w) => ({ workspace_id: idOf(w), name: nameOf(w) || null }));

return [{ json: { ...base, resolved: null, candidates, ambiguous: matches.length > 1 } }];
